/**
 * GET /api/sessions/events
 *
 * Server-Sent Events stream of session metadata changes. The chat page opens a
 * single long-lived connection here for the lifetime of the tab, so a rename
 * lands in the sidebar (and the browser tab title) the moment it is committed
 * to the database instead of whenever the client happens to re-fetch
 * `GET /api/sessions` next.
 *
 * This exists because conversation titles are generated by an LLM *after* the
 * response finishes streaming. The chat SSE stream has already closed by then,
 * so there was no channel left to report the new name on — the client used to
 * guess with a single 2-second timer, which silently lost the race whenever
 * title generation took longer than that.
 *
 * Wire format: `event: session-renamed\ndata: <json>\n\n`, where `<json>` is a
 * `SessionEvent` from `services/sessionEvents.ts`.
 *
 * No initial snapshot is sent: the client already loads the full list from
 * `GET /api/sessions` on mount, and a snapshot here would just duplicate it.
 *
 * Keep-alive: a `: keep-alive` comment every 15s to defeat idle-timeout
 * proxies.
 */

import type { NextRequest } from 'next/server';

import { type SessionEvent, subscribeSessionEvents } from '@/services/sessionEvents';
import { SESSIONS_SSE_EVENT_NAME } from '@/services/sseNames';

export const dynamic = 'force-dynamic';
export const runtime = 'nodejs';

const KEEPALIVE_MS = 15_000;

export async function GET(request: NextRequest): Promise<Response> {
  const encoder = new TextEncoder();

  let unsubscribe: (() => void) | null = null;
  let keepaliveTimer: ReturnType<typeof setInterval> | null = null;
  let closed = false;

  const teardown = (): void => {
    closed = true;
    if (unsubscribe) {
      unsubscribe();
      unsubscribe = null;
    }
    if (keepaliveTimer) {
      clearInterval(keepaliveTimer);
      keepaliveTimer = null;
    }
  };

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      const safeEnqueue = (chunk: string): void => {
        if (closed) return;
        try {
          controller.enqueue(encoder.encode(chunk));
        } catch {
          // Controller was already closed by the runtime — the client is
          // gone. Release the subscription and the timer now rather than
          // waiting for the abort signal to notice.
          teardown();
        }
      };

      // Subscribe first so we never miss an event that fires while the
      // stream is still being wired up.
      unsubscribe = subscribeSessionEvents((event: SessionEvent) => {
        safeEnqueue(`event: ${SESSIONS_SSE_EVENT_NAME}\ndata: ${JSON.stringify(event)}\n\n`);
      });

      keepaliveTimer = setInterval(() => {
        safeEnqueue(`: keep-alive\n\n`);
      }, KEEPALIVE_MS);

      const teardownStream = (): void => {
        // `teardown` is idempotent, so this is safe even if a failed enqueue
        // already ran it.
        teardown();
        try {
          controller.close();
        } catch {
          // Already closed — fine.
        }
      };

      // A disconnect (tab closed, navigation, dev HMR reload) must release
      // both the subscription and the timer.
      request.signal.addEventListener('abort', teardownStream);
    },
    cancel() {
      // The consumer side closed the stream (browser navigated away,
      // network dropped). Same teardown as the abort handler, minus the
      // controller close (the runtime already closed it).
      teardown();
    },
  });

  return new Response(stream, {
    status: 200,
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      // Disable Nginx-style response buffering so frames are flushed as
      // soon as we enqueue them.
      'X-Accel-Buffering': 'no',
    },
  });
}
